// 2. Outbox Worker (Polling Loop an toàn)
async function pollOutbox(batchSize = 50) {
  const events = await db.$queryRaw`
    SELECT * FROM outbox_events 
    WHERE status = 'PENDING'
    ORDER BY created_at ASC 
    LIMIT ${batchSize} 
    FOR UPDATE SKIP LOCKED
  `;
  for (const event of events) {
    try {
      await messageBroker.publish(event.event_type, JSON.parse(event.payload));
      await db.outboxEvents.update({
        where: { id: event.id },
        data: { status: 'PROCESSED', processedAt: new Date() }
      });
    } catch (err) {
      await db.outboxEvents.update({
        where: { id: event.id },
        data: { retryCount: { increment: 1 }, lastError: err.message }
      });
    }
  }
}

export function idempotencyMiddleware(redis: RedisClient) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const key = req.headers['idempotency-key'] as string;
    if (!key || req.method === 'GET') return next();

    const redisKey = `idemp:${req.user?.id || 'anon'}:${key}`;
    // Thử chiếm lock trạng thái IN_PROGRESS trong 60 giây
    const acquired = await redis.set(redisKey, JSON.stringify({ status: 'IN_PROGRESS' }), 'NX', 'EX', 60);

    if (!acquired) {
      const cached = JSON.parse(await redis.get(redisKey) || '{}');
      if (cached.status === 'IN_PROGRESS') {
        return res.status(409).json({ error: 'Concurrent request in progress' });
      }
      if (cached.status === 'SUCCESS') {
        return res.status(cached.statusCode).json(cached.body);
      }
    }

    // Hook vào hàm res.send để bắt response lưu lại Redis
    const originalSend = res.send.bind(res);
    res.send = (body: any) => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        redis.set(redisKey, JSON.stringify({
          status: 'SUCCESS',
          statusCode: res.statusCode,
          body: JSON.parse(body)
        }), 'EX', 86400); // Lưu 24h
      } else {
        redis.del(redisKey); // Lỗi thì giải phóng để retry
      }
      return originalSend(body);
    };
    next();
  };
}

import CircuitBreaker from 'opossum';

const options = {
  timeout: 3000, // Nếu request quá 3s coi như fail
  errorThresholdPercentage: 50, // Nếu 50% request lỗi -> OPEN mạch
  resetTimeout: 30000 // Chờ 30s trước khi thử HALF-OPEN
};

async function callExternalPayment(data) {
  return await httpClient.post('/charge', data);
}

const breaker = new CircuitBreaker(callExternalPayment, options);

// Kịch bản fallback khi mạch đang OPEN hoặc timeout
breaker.fallback(() => {
  return { status: 'PENDING_OFFLINE', message: 'Hệ thống thanh toán đang bận, đơn sẽ duyệt sau' };
});

export async function processPayment(paymentData) {
  return await breaker.fire(paymentData);
}

const flightMap = new Map<string, Promise<any>>();

export async function getWithSingleFlight<T>(
  key: string,
  ttlSeconds: number,
  fetchDbFn: () => Promise<T>
): Promise<T> {
  // 1. Kiểm tra cache Redis
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  // 2. Chống Stampede: Nếu đang có 1 promise khác query key này -> đợi chung
  if (flightMap.has(key)) {
    return await flightMap.get(key);
  }

  // 3. Là request đầu tiên: Tạo Promise đại diện
  const promise = (async () => {
    try {
      const dbData = await fetchDbFn();
      const jitter = Math.floor(Math.random() * 60); // Random Jitter tránh hết hạn đồng loạt
      await redis.set(key, JSON.stringify(dbData), 'EX', ttlSeconds + jitter);
      return dbData;
    } finally {
      flightMap.delete(key); // Xóa khỏi danh sách bay
    }
  })();

  flightMap.set(key, promise);
  return await promise;
}

interface SagaStep<TContext> {
  name: string;
  execute: (ctx: TContext) => Promise<void>;
  compensate: (ctx: TContext) => Promise<void>;
}

export class SagaOrchestrator<TContext> {
  private executedSteps: SagaStep<TContext>[] = [];
  constructor(private steps: SagaStep<TContext>[]) {}

  async execute(ctx: TContext) {
    for (const step of this.steps) {
      try {
        await step.execute(ctx);
        this.executedSteps.push(step);
      } catch (err) {
        console.error(`Step ${step.name} failed! Starting compensation...`);
        await this.rollback(ctx);
        throw err;
      }
    }
  }

  private async rollback(ctx: TContext) {
    for (const step of this.executedSteps.reverse()) {
      try {
        await step.compensate(ctx);
      } catch (compErr) {
        console.error(`FATAL: Compensation for ${step.name} failed! Needs manual review`, compErr);
      }
    }
  }
}

