async function processNextJobs(batchSize = 5) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const { rows: jobs } = await client.query(`
      SELECT * FROM background_jobs
      WHERE status = 'PENDING' AND run_at <= NOW()
      ORDER BY created_at ASC
      LIMIT $1
      FOR UPDATE SKIP LOCKED
    `, [batchSize]);

    for (const job of jobs) {
      try {
        await executeJobHandler(job.job_type, JSON.parse(job.payload));
        await client.query('UPDATE background_jobs SET status = \'DONE\', completed_at = NOW() WHERE id = $1', [job.id]);
      } catch (err) {
        await client.query('UPDATE background_jobs SET retry_count = retry_count + 1, last_error = $1 WHERE id = $2', [err.message, job.id]);
