    }
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
  } finally {
    client.release();
  }
}

import crypto from 'node:crypto';
import { Request, Response, NextFunction } from 'express';

export function verifyWebhookSignature(secretKey: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    const signature = req.headers['x-signature'] as string;
    if (!signature) {
      return res.status(401).json({ error: 'Missing signature header' });
    }

    const rawBody = (req as any).rawBody || Buffer.from(JSON.stringify(req.body));
    const computed = crypto
      .createHmac('sha256', secretKey)
      .update(rawBody)
      .digest('hex');

    const sigBuffer = Buffer.from(signature);
    const compBuffer = Buffer.from(computed);

    if (sigBuffer.length !== compBuffer.length || !crypto.timingSafeEqual(sigBuffer, compBuffer)) {
      return res.status(401).json({ error: 'Invalid webhook signature' });
    }

    next();
  };
}

async function purchaseProduct(productId: string, quantityToBuy: number) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('SET LOCAL lock_timeout = \'3s\'');

    const { rows } = await client.query(
      'SELECT id, stock FROM products WHERE id = $1 FOR UPDATE',
      [productId]
    );

    if (rows.length === 0) throw new Error('Product not found');
    const currentStock = rows[0].stock;

    if (currentStock < quantityToBuy) {
      throw new Error('Out of stock!');
    }

    await client.query(
      'UPDATE products SET stock = stock - $1 WHERE id = $2',
      [quantityToBuy, productId]
    );

    await client.query('COMMIT');
    return { success: true };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
